    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.personId = container.decodeLenient(Int64.self, forKey: .personId)
        self.abbreviatedId = container.decodeLenient(Int64.self, forKey: .abbreviatedId)
        self.personCode = container.decodeLenient(String.self, forKey: .personCode)
        self.surname = container.decodeLenient(String.self, forKey: .surname)
        self.name = container.decodeLenient(String.self, forKey: .name)
        self.patronymic = container.decodeLenient(String.self, forKey: .patronymic)
        self.birthDate = container.decodeLenient(String.self, forKey: .birthDate)
        self.birthMunicipalityId = container.decodeLenient(Int64.self, forKey: .birthMunicipalityId)
        self.birthMunicipalityCode = container.decodeLenient(String.self, forKey: .birthMunicipalityCode)
        self.birthMunicipalityCadastralCode = container.decodeLenient(String.self, forKey: .birthMunicipalityCadastralCode)
        self.birthMunicipalityMiurIstatCode = container.decodeLenient(String.self, forKey: .birthMunicipalityMiurIstatCode)
        self.birthMunicipalityDescription = container.decodeLenient(String.self, forKey: .birthMunicipalityDescription)
        self.birthNationId = container.decodeLenient(Int64.self, forKey: .birthNationId)
        self.birthNationCode = container.decodeLenient(String.self, forKey: .birthNationCode)
        self.birthForeignCity = container.decodeLenient(String.self, forKey: .birthForeignCity)
        self.birthMunicipalityAbbreviation = container.decodeLenient(String.self, forKey: .birthMunicipalityAbbreviation)
        self.birthProvinceDescription = container.decodeLenient(String.self, forKey: .birthProvinceDescription)
        self.birthCountryCode = container.decodeLenient(String.self, forKey: .birthCountryCode)
        self.birthNationDescription = container.decodeLenient(String.self, forKey: .birthNationDescription)
