public struct Esse3ValidationFlag: Codable, Hashable, Sendable {
    /// flag che rappresenta la validazone della foto. 1 foto valida, altrimenti 0.
    public var validationFlag: Int?

    public init(
        validationFlag: Int? = nil
    ) {
        self.validationFlag = validationFlag
    }

    private enum CodingKeys: String, CodingKey {
        case validationFlag = "validaFlg"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.validationFlag = container.decodeLenient(Int.self, forKey: .validationFlag)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(validationFlag, forKey: .validationFlag)
    }
}

