public struct Esse3HandicapTypesLookup: Codable, Hashable, Sendable {
    /// Codice tipo handicap.
    public var handicapType: String?
    /// Descrizione tipo handicap.
    public var description: String?
    /// Indica che la tipologia di handicap non abilita l'inserimento di percentuali.
    public var disabilityPercentageFlag: Int?
    /// Indica che la tipologia di handicap è una disabilità (invalidità riconosciuta ASL).
    public var disabilityFlag: Int?
    /// Indica che la tipologia di handicap è una invalidità legge 104 (riconosciuta da INPS).
    public var law104Flag: Int?
    /// Indica l'ordine in cui devono essere presentate le tipologie di invalidità da web. Se 0 non viene visualizzato, se 1 è quello preselezionato.
    public var orderWeb: Int?

    public init(
        handicapType: String? = nil,
        description: String? = nil,
        disabilityPercentageFlag: Int? = nil,
        disabilityFlag: Int? = nil,
        law104Flag: Int? = nil,
        orderWeb: Int? = nil
    ) {
        self.handicapType = handicapType
        self.description = description
        self.disabilityPercentageFlag = disabilityPercentageFlag
        self.disabilityFlag = disabilityFlag
        self.law104Flag = law104Flag
        self.orderWeb = orderWeb
    }

    private enum CodingKeys: String, CodingKey {
        case handicapType = "tipoHandicap"
        case description = "des"
        case disabilityPercentageFlag = "disabilPercFlg"
        case disabilityFlag = "disabilitaFlg"
        case law104Flag = "flg104"
        case orderWeb = "ordWeb"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.handicapType = container.decodeLenient(String.self, forKey: .handicapType)
        self.description = container.decodeLenient(String.self, forKey: .description)
        self.disabilityPercentageFlag = container.decodeLenient(Int.self, forKey: .disabilityPercentageFlag)
        self.disabilityFlag = container.decodeLenient(Int.self, forKey: .disabilityFlag)
        self.law104Flag = container.decodeLenient(Int.self, forKey: .law104Flag)
        self.orderWeb = container.decodeLenient(Int.self, forKey: .orderWeb)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(handicapType, forKey: .handicapType)
        try container.encode(description, forKey: .description)
        try container.encode(disabilityPercentageFlag, forKey: .disabilityPercentageFlag)
        try container.encode(disabilityFlag, forKey: .disabilityFlag)
        try container.encode(law104Flag, forKey: .law104Flag)
        try container.encode(orderWeb, forKey: .orderWeb)
    }
}

