public struct Esse3ItalianTitleAttachmentMetadata: Codable, Hashable, Sendable {
    /// nome del file
    public var fileName: String
    /// autore del file
    public var author: String?
    /// titolo del file
    public var title: String
    /// descrizione libera
    public var description: String
    /// tipologia dell'allegato relativo all'entità p17_tipologia_allegati
    public var attachmentTypology: String?
    /// flag che indica se l'allegato deve già risultare validato o meno
    public var validFlag: Int
    /// Anno Accademico di conseguimento del titolo
    public var academicYearAwardedTitle: Int
    /// codice tipo titolo italiano
    public var titleCategoryCode: String
    /// identificativo del titolo
    public var italianTitleId: Int64?

    public init(
        fileName: String = "",
        author: String? = nil,
        title: String = "",
        description: String = "",
        attachmentTypology: String? = nil,
        validFlag: Int = 0,
        academicYearAwardedTitle: Int = 0,
        titleCategoryCode: String = "",
        italianTitleId: Int64? = nil
    ) {
        self.fileName = fileName
        self.author = author
        self.title = title
        self.description = description
        self.attachmentTypology = attachmentTypology
        self.validFlag = validFlag
        self.academicYearAwardedTitle = academicYearAwardedTitle
        self.titleCategoryCode = titleCategoryCode
        self.italianTitleId = italianTitleId
    }

    private enum CodingKeys: String, CodingKey {
        case fileName = "filename"
        case author = "autore"
        case title = "titolo"
        case description = "descrizione"
        case attachmentTypology = "tipologiaAllegato"
        case validFlag = "validoFlg"
        case academicYearAwardedTitle = "aaConsegTit"
        case titleCategoryCode = "tipoTititCod"
        case italianTitleId = "titItId"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.fileName = container.decodeLenient(String.self, forKey: .fileName) ?? ""
        self.author = container.decodeLenient(String.self, forKey: .author)
        self.title = container.decodeLenient(String.self, forKey: .title) ?? ""
        self.description = container.decodeLenient(String.self, forKey: .description) ?? ""
        self.attachmentTypology = container.decodeLenient(String.self, forKey: .attachmentTypology)
        self.validFlag = container.decodeLenient(Int.self, forKey: .validFlag) ?? 0
        self.academicYearAwardedTitle = container.decodeLenient(Int.self, forKey: .academicYearAwardedTitle) ?? 0
        self.titleCategoryCode = container.decodeLenient(String.self, forKey: .titleCategoryCode) ?? ""
        self.italianTitleId = container.decodeLenient(Int64.self, forKey: .italianTitleId)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(fileName, forKey: .fileName)
