public struct Esse3HighSchoolDiplomaAttachmentMetadata: Codable, Hashable, Sendable {
    /// nome del file
    public var fileName: String
    /// autore del file
    public var author: String?
    /// titolo del file
    public var title: String
    /// descrizione libera
    public var description: String
    /// tipologia dell'allegato relativo all'entità p17_tipologia_allegati
    public var attachmentTypology: String?
    /// flag che indica se l'allegato deve già risultare validato o meno
    public var validFlag: Int
    /// anno di maturità, coincide con l'anno solare della data di conseguimento del diploma. Per esempio, anno scolastico 2019/2020, l'anno di diploma è 2020
    public var highSchoolGraduationYear: Int
    /// identificativo diploma MIUR
    public var miurDiplomaId: Int64?
    /// data di maturità
    public var highSchoolGraduationDate: String?
    /// identificativo della maturità
    public var highSchoolGraduationId: Int64?

    public init(
        fileName: String = "",
        author: String? = nil,
        title: String = "",
        description: String = "",
        attachmentTypology: String? = nil,
        validFlag: Int = 0,
        highSchoolGraduationYear: Int = 0,
        miurDiplomaId: Int64? = nil,
        highSchoolGraduationDate: String? = nil,
        highSchoolGraduationId: Int64? = nil
    ) {
        self.fileName = fileName
        self.author = author
        self.title = title
        self.description = description
        self.attachmentTypology = attachmentTypology
        self.validFlag = validFlag
        self.highSchoolGraduationYear = highSchoolGraduationYear
        self.miurDiplomaId = miurDiplomaId
        self.highSchoolGraduationDate = highSchoolGraduationDate
        self.highSchoolGraduationId = highSchoolGraduationId
    }

    private enum CodingKeys: String, CodingKey {
        case fileName = "filename"
        case author = "autore"
        case title = "titolo"
        case description = "descrizione"
        case attachmentTypology = "tipologiaAllegato"
        case validFlag = "validoFlg"
        case highSchoolGraduationYear = "annoMaturita"
        case miurDiplomaId = "idDiplomaMiur"
        case highSchoolGraduationDate = "dataMaturita"
        case highSchoolGraduationId = "maturId"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.fileName = container.decodeLenient(String.self, forKey: .fileName) ?? ""
        self.author = container.decodeLenient(String.self, forKey: .author)
        self.title = container.decodeLenient(String.self, forKey: .title) ?? ""
        self.description = container.decodeLenient(String.self, forKey: .description) ?? ""
        self.attachmentTypology = container.decodeLenient(String.self, forKey: .attachmentTypology)
        self.validFlag = container.decodeLenient(Int.self, forKey: .validFlag) ?? 0
        self.highSchoolGraduationYear = container.decodeLenient(Int.self, forKey: .highSchoolGraduationYear) ?? 0
        self.miurDiplomaId = container.decodeLenient(Int64.self, forKey: .miurDiplomaId)
        self.highSchoolGraduationDate = container.decodeLenient(String.self, forKey: .highSchoolGraduationDate)
        self.highSchoolGraduationId = container.decodeLenient(Int64.self, forKey: .highSchoolGraduationId)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(fileName, forKey: .fileName)
        try container.encode(author, forKey: .author)
        try container.encode(title, forKey: .title)
        try container.encode(description, forKey: .description)
        try container.encode(attachmentTypology, forKey: .attachmentTypology)
        try container.encode(validFlag, forKey: .validFlag)
        try container.encode(highSchoolGraduationYear, forKey: .highSchoolGraduationYear)
        try container.encode(miurDiplomaId, forKey: .miurDiplomaId)
        try container.encode(highSchoolGraduationDate, forKey: .highSchoolGraduationDate)
        try container.encode(highSchoolGraduationId, forKey: .highSchoolGraduationId)
    }
