        try container.encode(systemFlag, forKey: .systemFlag)
        try container.encode(schoolCode, forKey: .schoolCode)
        try container.encode(stateFlag, forKey: .stateFlag)
        try container.encode(referenceSchoolCode, forKey: .referenceSchoolCode)
    }
}

